class H264DecoderConfig(TypedDict, total=False):
    """`H264Decoder`'s config: the keys `stream_builder.add` takes."""

    max_height: int | None
    """Upper bound on the coded height, paired with `max_width`."""

    max_width: int | None
    """Upper bound on the coded width the DPB is allocated for. Absent: auto-detected
    from the first SPS. It caps the extent together with `max_height` or not at all: a
    half-specified pair warns and auto-detects both. On macOS, where CoreMedia reports
    only the cropped extent, a stream whose pictures pass the pair is refused by name.
    """


class H264Decoder(BuiltInNode[H264DecoderConfig]):
    """Decodes H.264 media frames to published video surfaces via hardware decode —
    Vulkan Video on Linux, VideoToolbox on macOS.

    `encoded_video` takes media frames in the layout `H264Encoder` publishes and the
    moq-dev players read — a QUIC varint timestamp, then one Annex-B access unit, a
    keyframe opening a group — from any producer; a message that is not one is refused
    by name. The decoder enters the stream at a group start and, after a read reports a
    loss, discards to the next one, so it never publishes a picture built from
    references it did not see. A keyframe whose parameter sets differ from the ones
    before it reconfigures the session. `video` publishes an ordinary `VideoFrame` on a
    pooled RGBA pixel-buffer surface at the conformance-windowed extent — never the
    coded picture — carrying the message's timestamp and the `color_info` the picture
    was converted with: the SPS VUI's, its matrix and range filled when the stream
    leaves them out (BT.709 for HD, BT.601 for SD, limited range); a matrix no converter
    represents is refused. `fps`, `texture_layout` and the HDR sidecars are absent, so
    an encoder and a `read(port, into=VideoFrame)` consume it unchanged. A decoded frame
    is buffer-backed, so it reaches a Python kernel through a DLPack landing copy, never
    by bare surface id.

    The decode session is minted at `setup()`. On a device with no hardware decoder for
    the codec — no Vulkan Video decode queue, or no VideoToolbox hardware decoder —
    setup refuses by name: the node never reaches Running, and waiting for every node to
    run raises rather than the graph running with an empty channel.

    Inputs:
        `encoded_video` (ordered): H.264 media frames to decode.

    Outputs:
        `video`: Decoded video frames.
            Catalog entry: `BinaryEntry(mode="snapshot", mime="application/msgpack")`.

    Config: `H264DecoderConfig`.
    """

    type: ClassVar[str] = "tatolab.stream:H264Decoder"


class H264EncoderConfig(TypedDict, total=False):
    """`H264Encoder`'s config: the keys `stream_builder.add` takes."""

    bitrate_bps: int | None
    """Target bitrate in bits per second. Absent: constant-QP encoding at the session's
    balanced preset.
    """

    effort_level: int | None
    """Encoder-effort index (the hardware encoder's analysis budget, not a codec quality
    knob). Absent: the codec's default. VideoToolbox has no effort index, so on macOS
    any value is refused by name at `setup()`.
    """

    fps: int | None
    """Frame rate used when the incoming frames carry none. Absent: 60."""

    height: int | None
    """Expected frame height — a guardrail like `width`."""

    keyframe_interval_seconds: int | None
    """Seconds between IDR sync points. Absent: 2. On macOS, 0 is refused by name at
    `setup()`.
    """

    width: int | None
    """Expected frame width — a guardrail, not a resize: a mismatching frame wins with a
    warning.
    """


class H264Encoder(BuiltInNode[H264EncoderConfig]):
    """Encodes published video surfaces to H.264 via hardware encode — Vulkan Video on
    Linux, VideoToolbox on macOS.

    `video` takes any published `VideoFrame` — buffer-backed (camera, test pattern) or
    texture-backed (a kernel output). `encoded_video` publishes one media frame per
    access unit, the layout the moq-dev players read: a QUIC varint timestamp in
    microseconds, then the Annex-B access unit, parameter sets inline before each
    keyframe. A keyframe opens a group. After its first frame the port's catalog entry
    is a `VideoEntry` naming the codec string the stream's SPS spells and the coded
    extent, with no `description`. A frame the encoder cannot consume is logged and
    dropped while the node keeps running; a frame its producer recycled before the
    encoder claimed it is counted as a drop on the `video` link, never an error; a write
    the channel ceiling refuses makes the next frame a keyframe. The session mints from
    the first frame's dimensions and re-mints when the upstream extent changes.

    On a device without a hardware encoder for the codec the session fails to mint: the
    failure latches and every later frame is discarded with one error line; no exception
    reaches Python.

    Inputs:
        `video` (ordered): Video frames to encode.

    Outputs:
        `encoded_video`: H.264 media frames, one access unit each.

    Config: `H264EncoderConfig`.
    """

    type: ClassVar[str] = "tatolab.stream:H264Encoder"


